export const registerCheckCommand = (
  program: Command,
  dependencies: Required<BuildCliDependencies>,
): void => {
  program
    .command("check")
    .description("Validate required configuration before running ingest work")
    .action(async () => {
      try {
        const config = dependencies.loadConfig();
        const sourceClient = dependencies.createSourceClient(config);
        // One S3 client + one pg pool per command, built once at the
        // composition root and injected into the read-only probes
        // ([std: correctness] External adapters one-client rule).
        const s3Client = dependencies.createS3Client(config.s3);
        const pool = dependencies.createPgPool(config.staging.databaseUrl);
        const sourceConnectivity = await dependencies.checkSourceConnectivity({
          sourceClient,
          sourceUrl: new URL(config.sourceUrl),
        });
        const s3Connectivity = await dependencies.checkS3Connectivity({
          bucket: config.s3.bucket,
          sender: s3Client,
        });
        const stagingConnectivity = await runStagingCheck(dependencies, pool);
        const checks = {
          s3Connectivity,
          sourceConnectivity,
          stagingConnectivity,
        };
        const ok = connectivityOk(checks);

        writeJson({
          ok,
          checks: {
            config: { status: "passed" },
            ...checks,
          },
          config: redactConfig(config),
        });

        if (!ok) {
          process.exitCode = 2;
        }
      } catch (error) {
        if (error instanceof ConfigValidationError) {
          writeJson({
            ok: false,
            checks: {
              config: { status: "failed" },
            },
            issues: error.issues,
          });
          process.exitCode = 2;
          return;
        }

        throw error;
      }
    });
};

const runWithRetry = async <TResult>(
  wiring: RetryWiring<TResult>,
  options?: SourceFetchOptions,
): Promise<TResult> => {
  const attempts = options?.attempts ?? noRetryAttempts;
  const callerSignal = options?.signal ?? new AbortController().signal;

  let retryOptions: RetrySourceReadOptions<TResult> = {
    attempts,
    classify: wiring.classify,
    phase: wiring.phase,
    read: wiring.read,
    signal: callerSignal,
    url: wiring.url.toString(),
  };

  if (options?.page !== undefined) {
    retryOptions = { ...retryOptions, page: options.page };
  }

  if (options?.onRetry !== undefined) {
    retryOptions = { ...retryOptions, onRetry: options.onRetry };
  }

  if (wiring.retryAfterMs !== undefined) {
    retryOptions = { ...retryOptions, retryAfterMs: wiring.retryAfterMs };
  }

  if (options?.sleep !== undefined) {
    retryOptions = { ...retryOptions, sleep: options.sleep };
  }

  if (options?.random !== undefined) {
    retryOptions = { ...retryOptions, random: options.random };
  }

  if (options?.now !== undefined) {
    retryOptions = { ...retryOptions, now: options.now };
  }

  return withRetry(retryOptions);
};

const assembleResult = async (
  input: RunOnceInput,
  context: AssembleResultInput,
): Promise<RunOnceResult> => {
  const sourceFailure = deriveSourceFailure(context.discoveryReport);
  const discoveredLastPage = deriveDiscoveredLastPage(context);
  const status = deriveRunStatus({
    discoveredLastPage,
    lastCompletedPage: context.lastCompletedPage,
    ok: context.discoveryReport.ok,
    reachedMaxPages: context.reachedMaxPages,
    ...sourceFailureOption(sourceFailure),
  });

  if (status === "complete") {
    await writeFinalCheckpoint(input, context, discoveredLastPage);
  }

  const summary = buildRunSummary({
    candidateCount: context.discoveryReport.candidates.length,
    discoveredLastPage,
    discoveryReport: context.discoveryReport,
    finishedAt: input.now().toISOString(),
    lastCompletedPage: context.lastCompletedPage,
    pageTimestampsMs: context.pageTimestampsMs,
    rawStorage: context.rawStorage,
    runId: input.runId,
    staging: context.staging,
    startedAt: context.startedAt,
    status,
    ...discoveredRangeOption(context.lastCompletedPage),
    ...resumeInvocationOption(status),
  });

  // D-03/D-04: emit run_complete (info) when the run finished every discovered
  // page, or run_partial (warn) for any non-complete status. The payload is
  // identifiers-only; the message is static.
  if (status === "complete") {
    input.log?.info(
      {
        event: "run_complete",
        runId: input.runId,
        status,
        counts: summary.counts,
      },
      "run complete",
    );
  } else {
    input.log?.warn(
      {
        event: "run_partial",
        runId: input.runId,
        status,
        counts: summary.counts,
      },
      "run partial",
    );
  }

  // D-12/D-13: opt-in evidence writes (independent, log-and-continue).
  // Each write is gated independently so both/either/neither may be active.
  await writeEvidence(input, summary);

  return {
    exitCode: runExitCode(summary),
    summary,
  };
};

const parseReplayRow = (
  rowHtml: string,
  page: number,
  sourceUrl: URL,
): ReplayRowObservation => {
  const cells = [
    ...rowHtml.matchAll(/<td[^>]*>(?<cell>[\s\S]*?)<\/td>/giu),
  ].map((match) => getMatchGroup(match, "cell"));
  const link =
    /<a\b[^>]*\bhref=(?<quote>["'])(?<href>.*?)\k<quote>[^>]*>(?<text>[\s\S]*?)<\/a>/iu.exec(
      cells[0] ?? "",
    );
  const href = link?.groups?.["href"]?.trim();
  const url = hrefToUrl(href, sourceUrl);
  const externalId = /\/replays\/(?<id>[^/?#]+)/iu.exec(url ?? "")?.groups?.[
    "id"
  ];
  const serverIdText = stripTags(cells[2] ?? "").trim();
  const serverId = Number.parseInt(serverIdText, 10);
  const source: MutableReplayRowSource = {};
  const metadata: MutableReplayRowMetadata = {};

  if (externalId !== undefined) {
    source.externalId = externalId;
  }

  if (url !== undefined) {
    source.url = url;
  }

  const missionText = stripTags(link?.groups?.["text"] ?? "").trim();
  const world = stripTags(cells[1] ?? "").trim();

  if (missionText.length > 0) {
    metadata.missionText = missionText;
  }

  if (world.length > 0) {
    metadata.world = world;
  }

  if (!Number.isNaN(serverId)) {
    metadata.serverId = serverId;
  }

  return {
    metadata,
    page,
    source,
  };
};

